const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.0/companies/%7Bcompany_id%7D/capital_planning/projects/%7Bprocore_project_id%7D/line_items',
  qs: {snapshot_id: 'SOME_STRING_VALUE'},
  headers: {'Procore-Company-Id': 'SOME_STRING_VALUE'}
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/companies/%7Bcompany_id%7D/capital_planning/projects/%7Bprocore_project_id%7D/line_items?snapshot_id=SOME_STRING_VALUE"),
    Headers =
    {
        { "Procore-Company-Id", "SOME_STRING_VALUE" },
    },
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

